  const currentActiveIndicesAsNumberArray: ValidatorIndex[] = [];
  const nextActiveIndicesAsNumberArray: ValidatorIndex[] = [];

  // BeaconChain could provide a shuffling cache to avoid re-computing shuffling every epoch

